// =========================================================
// QuantForge - Prepare Next Experiment
// =========================================================
// Purpose:
// 1. Prepare the next experiment after Critic
// 2. Increment experiment number
// 3. Use Critic's proposed configuration when available
// 4. If Critic ACCEPTED the current configuration,
//    deterministically create a new refinement
// 5. Never repeat an already-tested configuration
// 6. Preserve immutable research context
// =========================================================


// =========================================================
// CURRENT INPUT
// =========================================================

const current = $json;


// =========================================================
// BASIC CONTEXT
// =========================================================

const currentExperiment =
  Number(
    current.experiment || 1
  );

const maxExperiments =
  Number(
    current.max_experiments || 5
  );

const nextExperiment =
  currentExperiment + 1;


const instrument =
  current.instrument ||
  current.strategy_config?.data?.instrument;

const timeframe =
  current.timeframe ||
  current.strategy_config?.data?.timeframe;

const startingCapital =
  Number(
    current.starting_capital ??
    current.strategy_config?.capital?.starting_capital ??
    10000
  );

const researchRunId =
  current.research_run_id ||
  current.strategy_config?.research?.research_run_id;


const history =
  Array.isArray(current.history)
    ? current.history
    : [];


// =========================================================
// STOP PROTECTION
// =========================================================

if (
  nextExperiment > maxExperiments
) {

  return [{
    json: {

      ...current,

      experiment:
        nextExperiment,

      max_experiments:
        maxExperiments,

      final_experiment:
        true

    }
  }];

}


// =========================================================
// CURRENT STRATEGY CONFIG
// =========================================================

const currentConfig =
  current.strategy_config;


if (
  !currentConfig ||
  typeof currentConfig !== "object" ||
  Array.isArray(currentConfig)
) {

  throw new Error(
    "Prepare Next Experiment: strategy_config is missing."
  );

}


// =========================================================
// SIGNATURE FUNCTION
// =========================================================

function signature(config) {

  return JSON.stringify({

    strategy:
      config.strategy,

    parameters:
      config.parameters || {},

    stop_loss:
      config.risk?.stop_loss,

    take_profit:
      config.risk?.take_profit,

    lot_size:
      config.risk?.lot_size

  });

}


// =========================================================
// CHECK WHETHER CONFIG WAS ALREADY TESTED
// =========================================================

function alreadyTested(config) {

  const candidateSignature =
    signature(config);


  return history.some(
    record => {

      if (
        !record ||
        typeof record !== "object"
      ) {

        return false;

      }


      if (
        !record.strategy_config
      ) {

        return false;

      }


      return (
        signature(
          record.strategy_config
        ) ===
        candidateSignature
      );

    }
  );

}


// =========================================================
// DEEP COPY
// =========================================================

function clone(value) {

  return JSON.parse(
    JSON.stringify(value)
  );

}


// =========================================================
// NORMALIZE CONFIG
// =========================================================

function normalizeConfig(config) {

  const result =
    clone(config);


  result.data = {

    instrument:
      instrument,

    timeframe:
      timeframe

  };


  result.research = {

    research_run_id:
      researchRunId

  };


  result.capital = {

    starting_capital:
      startingCapital

  };


  return result;

}


// =========================================================
// CANDIDATE CONFIGURATIONS
// =========================================================

const candidates = [];


// =========================================================
// 1. CURRENT / CRITIC CONFIG
// =========================================================
//
// If Critic returned MODIFY, this may already contain
// a different strategy or different parameters.
//
// We try it first.
// =========================================================

const criticCandidate =
  normalizeConfig(
    currentConfig
  );

candidates.push(
  criticCandidate
);


// =========================================================
// STRATEGY-SPECIFIC REFINEMENT CANDIDATES
// =========================================================

const strategy =
  currentConfig.strategy;

const parameters =
  currentConfig.parameters || {};

const risk =
  currentConfig.risk || {};


// =========================================================
// EMA CROSSOVER
// =========================================================

if (
  strategy === "EMA_Crossover"
) {

  const fast =
    Number(
      parameters.fast_ema
    );

  const slow =
    Number(
      parameters.slow_ema
    );


  // Candidate A:
  // Slightly faster fast EMA

  if (
    fast > 5
  ) {

    candidates.push({

      strategy:
        "EMA_Crossover",

      parameters: {

        fast_ema:
          fast - 1,

        slow_ema:
          slow

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate B:
  // Slightly slower fast EMA

  if (
    fast < 30 &&
    fast + 1 < slow
  ) {

    candidates.push({

      strategy:
        "EMA_Crossover",

      parameters: {

        fast_ema:
          fast + 1,

        slow_ema:
          slow

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate C:
  // Increase slow EMA

  if (
    slow < 100
  ) {

    candidates.push({

      strategy:
        "EMA_Crossover",

      parameters: {

        fast_ema:
          fast,

        slow_ema:
          slow + 5

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate D:
  // Decrease slow EMA

  if (
    slow > 20 &&
    slow - 5 > fast
  ) {

    candidates.push({

      strategy:
        "EMA_Crossover",

      parameters: {

        fast_ema:
          fast,

        slow_ema:
          slow - 5

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate E:
  // Change to RSI family

  candidates.push({

    strategy:
      "RSI_Mean_Reversion",

    parameters: {

      rsi_period:
        14,

      oversold:
        30,

      overbought:
        70

    },

    risk:
      clone(risk),

    data: {

      instrument:
        instrument,

      timeframe:
        timeframe

    },

    research: {

      research_run_id:
        researchRunId

    },

    capital: {

      starting_capital:
        startingCapital

    }

  });


  // Candidate F:
  // Change to Supertrend

  candidates.push({

    strategy:
      "Supertrend",

    parameters: {

      atr_period:
        10,

      multiplier:
        3

    },

    risk:
      clone(risk),

    data: {

      instrument:
        instrument,

      timeframe:
        timeframe

    },

    research: {

      research_run_id:
        researchRunId

    },

    capital: {

      starting_capital:
        startingCapital

    }

  });

}


// =========================================================
// RSI MEAN REVERSION
// =========================================================

if (
  strategy === "RSI_Mean_Reversion"
) {

  const period =
    Number(
      parameters.rsi_period
    );

  const oversold =
    Number(
      parameters.oversold
    );

  const overbought =
    Number(
      parameters.overbought
    );


  // Candidate A:
  // Shorter RSI period

  if (
    period > 5
  ) {

    candidates.push({

      strategy:
        "RSI_Mean_Reversion",

      parameters: {

        rsi_period:
          period - 1,

        oversold:
          oversold,

        overbought:
          overbought

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate B:
  // Longer RSI period

  if (
    period < 30
  ) {

    candidates.push({

      strategy:
        "RSI_Mean_Reversion",

      parameters: {

        rsi_period:
          period + 1,

        oversold:
          oversold,

        overbought:
          overbought

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate C:
  // Wider oversold threshold

  if (
    oversold > 20
  ) {

    candidates.push({

      strategy:
        "RSI_Mean_Reversion",

      parameters: {

        rsi_period:
          period,

        oversold:
          oversold - 5,

        overbought:
          overbought

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate D:
  // Lower overbought threshold

  if (
    overbought > 60
  ) {

    candidates.push({

      strategy:
        "RSI_Mean_Reversion",

      parameters: {

        rsi_period:
          period,

        oversold:
          oversold,

        overbought:
          overbought - 5

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate E:
  // Switch to EMA

  candidates.push({

    strategy:
      "EMA_Crossover",

    parameters: {

      fast_ema:
        10,

      slow_ema:
        30

    },

    risk:
      clone(risk),

    data: {

      instrument:
        instrument,

      timeframe:
        timeframe

    },

    research: {

      research_run_id:
        researchRunId

    },

    capital: {

      starting_capital:
        startingCapital

    }

  });


  // Candidate F:
  // Switch to Supertrend

  candidates.push({

    strategy:
      "Supertrend",

    parameters: {

      atr_period:
        10,

      multiplier:
        3

    },

    risk:
      clone(risk),

    data: {

      instrument:
        instrument,

      timeframe:
        timeframe

    },

    research: {

      research_run_id:
        researchRunId

    },

    capital: {

      starting_capital:
        startingCapital

    }

  });

}


// =========================================================
// SUPERTREND
// =========================================================

if (
  strategy === "Supertrend"
) {

  const atrPeriod =
    Number(
      parameters.atr_period
    );

  const multiplier =
    Number(
      parameters.multiplier
    );


  // Candidate A:
  // Lower ATR period

  if (
    atrPeriod > 5
  ) {

    candidates.push({

      strategy:
        "Supertrend",

      parameters: {

        atr_period:
          atrPeriod - 1,

        multiplier:
          multiplier

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate B:
  // Higher ATR period

  if (
    atrPeriod < 30
  ) {

    candidates.push({

      strategy:
        "Supertrend",

      parameters: {

        atr_period:
          atrPeriod + 1,

        multiplier:
          multiplier

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate C:
  // Lower multiplier

  if (
    multiplier > 1
  ) {

    candidates.push({

      strategy:
        "Supertrend",

      parameters: {

        atr_period:
          atrPeriod,

        multiplier:
          Math.max(
            1,
            Number(
              (
                multiplier - 0.5
              ).toFixed(1)
            )
          )

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate D:
  // Higher multiplier

  if (
    multiplier < 5
  ) {

    candidates.push({

      strategy:
        "Supertrend",

      parameters: {

        atr_period:
          atrPeriod,

        multiplier:
          Math.min(
            5,
            Number(
              (
                multiplier + 0.5
              ).toFixed(1)
            )
          )

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate E:
  // Switch to EMA

  candidates.push({

    strategy:
      "EMA_Crossover",

    parameters: {

      fast_ema:
        10,

      slow_ema:
        30

    },

    risk:
      clone(risk),

    data: {

      instrument:
        instrument,

      timeframe:
        timeframe

    },

    research: {

      research_run_id:
        researchRunId

    },

    capital: {

      starting_capital:
        startingCapital

    }

  });


  // Candidate F:
  // Switch to RSI

  candidates.push({

    strategy:
      "RSI_Mean_Reversion",

    parameters: {

      rsi_period:
        14,

      oversold:
        30,

      overbought:
        70

    },

    risk:
      clone(risk),

    data: {

      instrument:
        instrument,

      timeframe:
        timeframe

    },

    research: {

      research_run_id:
        researchRunId

    },

    capital: {

      starting_capital:
        startingCapital

    }

  });

}


// =========================================================
// FIND FIRST UNUSED CANDIDATE
// =========================================================

let selectedConfig =
  null;


for (
  const candidate of candidates
) {

  const normalized =
    normalizeConfig(
      candidate
    );


  if (
    !alreadyTested(
      normalized
    )
  ) {

    selectedConfig =
      normalized;

    break;

  }

}


// =========================================================
// NO VALID CANDIDATE
// =========================================================

if (
  !selectedConfig
) {

  throw new Error(
    "Unable to create a new unique experiment configuration."
  );

}


// =========================================================
// FINAL OUTPUT
// =========================================================

return [{
  json: {

    decision:
      "MODIFY",

    retry_required:
      false,

    reason:
      "Prepared a new unique configuration for the next experiment.",

    research_run_id:
      researchRunId,

    instrument:
      instrument,

    timeframe:
      timeframe,

    starting_capital:
      startingCapital,

    experiment:
      nextExperiment,

    max_experiments:
      maxExperiments,

    strategy:
      selectedConfig.strategy,

    strategy_config:
      selectedConfig,

    history:
      history,

    fast_ema:
      selectedConfig.strategy === "EMA_Crossover"
        ? selectedConfig.parameters.fast_ema
        : null,

    slow_ema:
      selectedConfig.strategy === "EMA_Crossover"
        ? selectedConfig.parameters.slow_ema
        : null,

    rsi_period:
      selectedConfig.strategy === "RSI_Mean_Reversion"
        ? selectedConfig.parameters.rsi_period
        : null,

    oversold:
      selectedConfig.strategy === "RSI_Mean_Reversion"
        ? selectedConfig.parameters.oversold
        : null,

    overbought:
      selectedConfig.strategy === "RSI_Mean_Reversion"
        ? selectedConfig.parameters.overbought
        : null,

    atr_period:
      selectedConfig.strategy === "Supertrend"
        ? selectedConfig.parameters.atr_period
        : null,

    multiplier:
      selectedConfig.strategy === "Supertrend"
        ? selectedConfig.parameters.multiplier
        : null,

    stop_loss:
      selectedConfig.risk.stop_loss,

    take_profit:
      selectedConfig.risk.take_profit,

    lot_size:
      selectedConfig.risk.lot_size

  }
}];

// ============================================================
// QuantForge - Critic Code Parser
//
// Handles:
//   HTTP Request
//       ↓
//   Heat Analysis
//       ↓
//   Critic AI
//       ↓
//   Critic Code Parser
//
// Retry:
//   Critic Code Parser
//       ↓
//   Critic Decision Valid? = FALSE
//       ↓
//   Critic AI
//
// IMPORTANT:
// - Python/backtest remains source of truth.
// - Heat Analysis remains deterministic.
// - Critic AI proposes strategy configurations.
// - Parser can recover configurations from small-LLM prose.
// - Duplicate configurations get deterministic fallback.
// - Heat Analysis is preserved through retries.
// ============================================================

const MAX_RETRIES = 3;


// ============================================================
// HELPERS
// ============================================================

function deepClone(value) {
  return JSON.parse(JSON.stringify(value));
}


function safeNumber(value, fallback = null) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}


function isInteger(value) {
  return Number.isInteger(Number(value));
}


function makeSignature(config) {

  if (!config || typeof config !== "object") {
    return "";
  }

  const parameters = config.parameters || {};
  const risk = config.risk || {};

  return JSON.stringify({
    strategy: config.strategy || "",
    parameters,
    stop_loss: risk.stop_loss,
    take_profit: risk.take_profit,
    lot_size: risk.lot_size
  });
}


function normalizeStrategyConfig(config, context) {

  if (!config || typeof config !== "object") {
    return null;
  }

  return {
    strategy: config.strategy,

    parameters: {
      ...(config.parameters || {})
    },

    risk: {
      ...(config.risk || {})
    },

    data: {
      instrument: context.instrument,
      timeframe: context.timeframe
    },

    capital: {
      starting_capital: context.starting_capital
    },

    research: {
      research_run_id: context.research_run_id
    }
  };
}


// ============================================================
// EXTRACT JSON FROM LLM OUTPUT
// ============================================================

function extractJsonObject(text) {

  if (typeof text !== "string") {
    return null;
  }

  let cleaned = text.trim();

  // Remove markdown fences if present.
  cleaned = cleaned
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();


  // ----------------------------------------------------------
  // First attempt: entire response is JSON
  // ----------------------------------------------------------

  try {
    return JSON.parse(cleaned);
  } catch (e) {
    // Continue.
  }


  // ----------------------------------------------------------
  // Second attempt: find first balanced JSON object
  // ----------------------------------------------------------

  const firstBrace = cleaned.indexOf("{");

  if (firstBrace >= 0) {

    let depth = 0;
    let inString = false;
    let escaped = false;

    for (
      let i = firstBrace;
      i < cleaned.length;
      i++
    ) {

      const char = cleaned[i];

      if (escaped) {
        escaped = false;
        continue;
      }

      if (char === "\\") {
        escaped = true;
        continue;
      }

      if (char === '"') {
        inString = !inString;
        continue;
      }

      if (inString) {
        continue;
      }

      if (char === "{") {
        depth++;
      }

      if (char === "}") {
        depth--;

        if (depth === 0) {

          const candidate =
            cleaned.slice(
              firstBrace,
              i + 1
            );

          try {
            return JSON.parse(candidate);
          } catch (e) {
            break;
          }
        }
      }
    }
  }

  return null;
}


// ============================================================
// EXTRACT CONFIGURATION FROM PROSE
//
// This is specifically for llama3.2:3b outputs like:
//
// Decision: MODIFY
// Strategy: EMA_Crossover
// fast_ema: 20
// slow_ema: 30
// stop_loss: 0.001
// take_profit: 0.002
// lot_size: 5000
//
// It does NOT trust any performance metrics from the prose.
// Only the proposed configuration is extracted.
// ============================================================

function extractConfigurationFromProse(
  text,
  context
) {

  if (typeof text !== "string") {
    return null;
  }

  const normalized =
    text.replace(/\r/g, "");


  // ----------------------------------------------------------
  // Decision
  // ----------------------------------------------------------

  let decision = null;

  const decisionMatch =
    normalized.match(
      /(?:Decision|decision)\s*:\s*(MODIFY|ACCEPT)/i
    );

  if (decisionMatch) {
    decision =
      decisionMatch[1].toUpperCase();
  }


  // ----------------------------------------------------------
  // Strategy
  // ----------------------------------------------------------

  let strategy = null;

  const strategyMatch =
    normalized.match(
      /(?:Strategy|strategy)\s*:\s*(EMA_Crossover|RSI_Mean_Reversion|Supertrend)/i
    );

  if (strategyMatch) {

    const raw =
      strategyMatch[1];

    if (
      raw.toLowerCase() ===
      "ema_crossover"
    ) {
      strategy = "EMA_Crossover";
    }

    else if (
      raw.toLowerCase() ===
      "rsi_mean_reversion"
    ) {
      strategy = "RSI_Mean_Reversion";
    }

    else if (
      raw.toLowerCase() ===
      "supertrend"
    ) {
      strategy = "Supertrend";
    }
  }


  // ----------------------------------------------------------
  // Helper for extracting numeric values
  // ----------------------------------------------------------

  function extractNumber(
    fieldNames
  ) {

    for (
      const field of fieldNames
    ) {

      const regex =
        new RegExp(
          "(?:[+\\-•*]\\s*)?" +
          field.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") +
          "\\s*:\\s*(-?\\d+(?:\\.\\d+)?)",
          "i"
        );

      const match =
        normalized.match(regex);

      if (match) {
        return Number(match[1]);
      }
    }

    return null;
  }


  // ----------------------------------------------------------
  // Parameters
  // ----------------------------------------------------------

  let parameters = {};


  if (
    strategy ===
    "EMA_Crossover"
  ) {

    const fast =
      extractNumber([
        "fast_ema"
      ]);

    const slow =
      extractNumber([
        "slow_ema"
      ]);

    if (fast !== null) {
      parameters.fast_ema = fast;
    }

    if (slow !== null) {
      parameters.slow_ema = slow;
    }
  }


  if (
    strategy ===
    "RSI_Mean_Reversion"
  ) {

    const period =
      extractNumber([
        "rsi_period"
      ]);

    const oversold =
      extractNumber([
        "oversold"
      ]);

    const overbought =
      extractNumber([
        "overbought"
      ]);

    if (period !== null) {
      parameters.rsi_period = period;
    }

    if (oversold !== null) {
      parameters.oversold = oversold;
    }

    if (overbought !== null) {
      parameters.overbought = overbought;
    }
  }


  if (
    strategy ===
    "Supertrend"
  ) {

    const atrPeriod =
      extractNumber([
        "atr_period"
      ]);

    const multiplier =
      extractNumber([
        "multiplier"
      ]);

    if (atrPeriod !== null) {
      parameters.atr_period = atrPeriod;
    }

    if (multiplier !== null) {
      parameters.multiplier = multiplier;
    }
  }


  // ----------------------------------------------------------
  // Risk
  // ----------------------------------------------------------

  const stopLoss =
    extractNumber([
      "stop_loss"
    ]);

  const takeProfit =
    extractNumber([
      "take_profit"
    ]);

  const lotSize =
    extractNumber([
      "lot_size"
    ]);


  const risk = {};

  if (stopLoss !== null) {
    risk.stop_loss = stopLoss;
  }

  if (takeProfit !== null) {
    risk.take_profit = takeProfit;
  }

  if (lotSize !== null) {
    risk.lot_size = lotSize;
  }


  // ----------------------------------------------------------
  // We need at least a strategy and parameters.
  // ----------------------------------------------------------

  if (!strategy) {
    return null;
  }


  if (
    Object.keys(parameters).length === 0
  ) {
    return null;
  }


  return {

    decision:
      decision || "MODIFY",

    reason:
      "Configuration extracted from Critic AI response.",

    strategy_config: {

      strategy,

      parameters,

      risk,

      data: {
        instrument:
          context.instrument,

        timeframe:
          context.timeframe
      },

      capital: {
        starting_capital:
          context.starting_capital
      },

      research: {
        research_run_id:
          context.research_run_id
      }
    }
  };
}


// ============================================================
// PARSE CRITIC OUTPUT
// ============================================================

function parseCriticOutput(
  raw,
  context
) {

  // ----------------------------------------------------------
  // If already an object
  // ----------------------------------------------------------

  if (
    raw &&
    typeof raw === "object" &&
    !Array.isArray(raw)
  ) {

    return raw;
  }


  if (typeof raw !== "string") {

    throw new Error(
      "Critic AI returned an unsupported output format."
    );
  }


  // ----------------------------------------------------------
  // Try JSON
  // ----------------------------------------------------------

  const json =
    extractJsonObject(raw);

  if (json) {
    return json;
  }


  // ----------------------------------------------------------
  // Try structured prose extraction
  // ----------------------------------------------------------

  const proseConfig =
    extractConfigurationFromProse(
      raw,
      context
    );

  if (proseConfig) {

    return proseConfig;
  }


  throw new Error(
    "Critic AI response could not be parsed as JSON or as a recognizable strategy configuration."
  );
}


// ============================================================
// INPUT
// ============================================================

const incoming =
  $input.first().json;


// ============================================================
// AUTHORITATIVE HTTP REQUEST DATA
// ============================================================

const http =
  $("HTTP Request").first().json;


// ============================================================
// CONTEXT
// ============================================================

const context = {

  instrument:
    http.instrument ??
    incoming.instrument,

  timeframe:
    http.timeframe ??
    incoming.timeframe,

  starting_capital:
    safeNumber(
      http.initial_capital ??
      http.starting_capital ??
      incoming.starting_capital,
      10000
    ),

  research_run_id:
    http.research_run_id ??
    incoming.research_run_id,

  experiment:
    safeNumber(
      http.experiment ??
      incoming.experiment,
      1
    ),

  max_experiments:
    safeNumber(
      http.max_experiments ??
      incoming.max_experiments,
      1
    )
};


// ============================================================
// PYTHON METRICS
// ============================================================

const currentHeatScore =
  safeNumber(
    http.heat_score ??
    incoming.heat_score
  );

const currentHeatLabel =
  http.heat_label ??
  incoming.heat_label ??
  null;

const currentHeatChecks =
  http.heat_checks ??
  incoming.heat_checks ??
  {};

const baselineThresholds =
  http.baseline_thresholds ??
  incoming.baseline_thresholds ??
  {};


// ============================================================
// HISTORY
// ============================================================

let history = [];

if (Array.isArray(incoming.history)) {

  history =
    deepClone(
      incoming.history
    );

}

else if (Array.isArray(http.history)) {

  history =
    deepClone(
      http.history
    );
}


// ============================================================
// HEAT ANALYSIS
//
// First pass:
// comes from Heat Analysis.
//
// Retry:
// comes from Critic Code Parser's previous output.
//
// Preserve it.
// ============================================================

let heatAnalysis =
  incoming.heat_analysis || null;


// ------------------------------------------------------------
// Safety fallback
// ------------------------------------------------------------

if (!heatAnalysis) {

  let previousHeatScore = null;
  let previousHeatLabel = null;

  if (history.length > 0) {

    const previous =
      history[history.length - 1];

    previousHeatScore =
      safeNumber(
        previous.heat_score
      );

    previousHeatLabel =
      previous.heat_label ??
      null;
  }

  let heatChange = null;
  let heatAssessment = "BASELINE";

  if (
    previousHeatScore !== null &&
    currentHeatScore !== null
  ) {

    heatChange =
      currentHeatScore -
      previousHeatScore;

    if (heatChange > 0) {
      heatAssessment = "IMPROVED";
    }

    else if (heatChange < 0) {
      heatAssessment = "DECLINED";
    }

    else {
      heatAssessment = "UNCHANGED";
    }
  }

  heatAnalysis = {

    current_heat_score:
      currentHeatScore,

    current_heat_label:
      currentHeatLabel,

    previous_heat_score:
      previousHeatScore,

    previous_heat_label:
      previousHeatLabel,

    heat_change:
      heatChange,

    heat_assessment:
      heatAssessment
  };
}


// ============================================================
// RETRY COUNT
// ============================================================

const previousRetryCount =
  safeNumber(
    incoming.retry_count,
    0
  );


// ============================================================
// RAW CRITIC OUTPUT
// ============================================================

let rawCriticOutput =
  incoming.output ??
  incoming.text ??
  incoming.response ??
  incoming.content ??
  incoming;


// ============================================================
// RETRY RESPONSE
// ============================================================

function returnRetry(
  reasonText,
  rejectedConfiguration = null
) {

  const retryCount =
    previousRetryCount + 1;


  return [{
    json: {

      decision:
        "RETRY",

      retry_required:
        retryCount <= MAX_RETRIES,

      retry_count:
        retryCount,

      retry_reason:
        reasonText,

      reason:
        reasonText,

      rejected_configuration:
        rejectedConfiguration,

      strategy:
        http.strategy ??
        incoming.strategy,

      strategy_config:
        http.strategy_config ??
        incoming.strategy_config,

      instrument:
        context.instrument,

      timeframe:
        context.timeframe,

      starting_capital:
        context.starting_capital,

      research_run_id:
        context.research_run_id,

      experiment:
        context.experiment,

      max_experiments:
        context.max_experiments,

      return_percent:
        http.return_percent ??
        incoming.return_percent,

      trades:
        http.trades ??
        incoming.trades,

      win_rate:
        http.win_rate ??
        incoming.win_rate,

      profit_factor:
        http.profit_factor ??
        incoming.profit_factor,

      max_drawdown_percent:
        http.max_drawdown_percent ??
        incoming.max_drawdown_percent,

      sharpe_ratio:
        http.sharpe_ratio ??
        incoming.sharpe_ratio,

      heat_score:
        currentHeatScore,

      heat_label:
        currentHeatLabel,

      heat_checks:
        currentHeatChecks,

      baseline_thresholds:
        baselineThresholds,

      // CRITICAL:
      // Preserve deterministic Heat Analysis.
      heat_analysis:
        deepClone(
          heatAnalysis
        ),

      history:
        deepClone(
          history
        )
    }
  }];
}


// ============================================================
// PARSE
// ============================================================

let critic;

try {

  critic =
    parseCriticOutput(
      rawCriticOutput,
      context
    );

}

catch (error) {

  return returnRetry(
    error.message,
    null
  );
}


// ============================================================
// DECISION
// ============================================================

const decision =
  String(
    critic.decision || ""
  )
    .trim()
    .toUpperCase();


const reason =
  typeof critic.reason === "string"
    ? critic.reason
    : "No reason supplied by Critic.";


// ============================================================
// CONFIGURATION
// ============================================================

let proposedConfig =
  critic.strategy_config;


// ------------------------------------------------------------
// Alternative structure
// ------------------------------------------------------------

if (
  !proposedConfig &&
  critic.strategy
) {

  proposedConfig = {

    strategy:
      critic.strategy,

    parameters:
      critic.parameters || {},

    risk:
      critic.risk || {},

    data:
      critic.data || {},

    capital:
      critic.capital || {},

    research:
      critic.research || {}
  };
}


// ------------------------------------------------------------
// Normalize
// ------------------------------------------------------------

proposedConfig =
  normalizeStrategyConfig(
    proposedConfig,
    context
  );


// ============================================================
// DECISION VALIDATION
// ============================================================

if (
  decision !== "MODIFY" &&
  decision !== "ACCEPT"
) {

  return returnRetry(

    `Critic decision must be MODIFY or ACCEPT. Received: ${
      decision || "EMPTY"
    }`,

    proposedConfig
  );
}


// ============================================================
// CONFIG EXISTENCE
// ============================================================

if (!proposedConfig) {

  return returnRetry(
    "Critic did not provide a usable strategy configuration.",
    null
  );
}


// ============================================================
// SUPPORTED STRATEGIES
// ============================================================

const supportedStrategies = [
  "EMA_Crossover",
  "RSI_Mean_Reversion",
  "Supertrend"
];


if (
  !supportedStrategies.includes(
    proposedConfig.strategy
  )
) {

  return returnRetry(

    `Unsupported strategy: ${proposedConfig.strategy}`,

    proposedConfig
  );
}


// ============================================================
// IMMUTABLE VALUES
// ============================================================

if (
  proposedConfig.data.instrument !==
  context.instrument
) {

  return returnRetry(
    "Critic changed immutable instrument.",
    proposedConfig
  );
}


if (
  proposedConfig.data.timeframe !==
  context.timeframe
) {

  return returnRetry(
    "Critic changed immutable timeframe.",
    proposedConfig
  );
}


if (
  Number(
    proposedConfig.capital.starting_capital
  ) !==
  Number(
    context.starting_capital
  )
) {

  return returnRetry(
    "Critic changed immutable starting capital.",
    proposedConfig
  );
}


if (
  proposedConfig.research.research_run_id !==
  context.research_run_id
) {

  return returnRetry(
    "Critic changed immutable research_run_id.",
    proposedConfig
  );
}


// ============================================================
// PARAMETERS
// ============================================================

const p =
  proposedConfig.parameters || {};


// ------------------------------------------------------------
// EMA
// ------------------------------------------------------------

if (
  proposedConfig.strategy ===
  "EMA_Crossover"
) {

  const fast =
    safeNumber(
      p.fast_ema
    );

  const slow =
    safeNumber(
      p.slow_ema
    );

  if (
    fast === null ||
    slow === null ||
    !isInteger(fast) ||
    !isInteger(slow)
  ) {

    return returnRetry(
      "EMA parameters must be integers.",
      proposedConfig
    );
  }

  if (
    fast < 5 ||
    fast > 30
  ) {

    return returnRetry(
      "EMA fast_ema must be between 5 and 30.",
      proposedConfig
    );
  }

  if (
    slow < 20 ||
    slow > 100
  ) {

    return returnRetry(
      "EMA slow_ema must be between 20 and 100.",
      proposedConfig
    );
  }

  if (
    slow <= fast
  ) {

    return returnRetry(
      "EMA slow_ema must be greater than fast_ema.",
      proposedConfig
    );
  }
}


// ------------------------------------------------------------
// RSI
// ------------------------------------------------------------

if (
  proposedConfig.strategy ===
  "RSI_Mean_Reversion"
) {

  const period =
    safeNumber(
      p.rsi_period
    );

  const oversold =
    safeNumber(
      p.oversold
    );

  const overbought =
    safeNumber(
      p.overbought
    );

  if (
    period === null ||
    oversold === null ||
    overbought === null
  ) {

    return returnRetry(
      "RSI parameters are incomplete.",
      proposedConfig
    );
  }

  if (
    !isInteger(period) ||
    period < 5 ||
    period > 30
  ) {

    return returnRetry(
      "RSI rsi_period must be an integer between 5 and 30.",
      proposedConfig
    );
  }

  if (
    oversold < 20 ||
    oversold > 40
  ) {

    return returnRetry(
      "RSI oversold must be between 20 and 40.",
      proposedConfig
    );
  }

  if (
    overbought < 60 ||
    overbought > 80
  ) {

    return returnRetry(
      "RSI overbought must be between 60 and 80.",
      proposedConfig
    );
  }

  if (
    oversold >= overbought
  ) {

    return returnRetry(
      "RSI oversold must be lower than overbought.",
      proposedConfig
    );
  }
}


// ------------------------------------------------------------
// SUPERTREND
// ------------------------------------------------------------

if (
  proposedConfig.strategy ===
  "Supertrend"
) {

  const atrPeriod =
    safeNumber(
      p.atr_period
    );

  const multiplier =
    safeNumber(
      p.multiplier
    );

  if (
    atrPeriod === null ||
    multiplier === null
  ) {

    return returnRetry(
      "Supertrend parameters are incomplete.",
      proposedConfig
    );
  }

  if (
    !isInteger(atrPeriod) ||
    atrPeriod < 5 ||
    atrPeriod > 30
  ) {

    return returnRetry(
      "Supertrend atr_period must be an integer between 5 and 30.",
      proposedConfig
    );
  }

  if (
    multiplier < 1 ||
    multiplier > 5
  ) {

    return returnRetry(
      "Supertrend multiplier must be between 1 and 5.",
      proposedConfig
    );
  }
}


// ============================================================
// RISK
// ============================================================

const risk =
  proposedConfig.risk || {};

const stopLoss =
  safeNumber(
    risk.stop_loss
  );

const takeProfit =
  safeNumber(
    risk.take_profit
  );

const lotSize =
  safeNumber(
    risk.lot_size
  );


if (
  stopLoss === null ||
  stopLoss <= 0
) {

  return returnRetry(
    "stop_loss must be greater than zero.",
    proposedConfig
  );
}


if (
  takeProfit === null ||
  takeProfit <= 0
) {

  return returnRetry(
    "take_profit must be greater than zero.",
    proposedConfig
  );
}


if (
  lotSize === null ||
  lotSize <= 0
) {

  return returnRetry(
    "lot_size must be greater than zero.",
    proposedConfig
  );
}


if (
  lotSize >
  context.starting_capital
) {

  return returnRetry(
    "lot_size cannot exceed starting capital.",
    proposedConfig
  );
}


// ============================================================
// SIGNATURES
// ============================================================

const proposedSignature =
  makeSignature(
    proposedConfig
  );

const currentSignature =
  makeSignature(
    http.strategy_config ??
    incoming.strategy_config
  );


// ============================================================
// TESTED CONFIGURATIONS
// ============================================================

const testedSignatures =
  new Set();


if (currentSignature) {

  testedSignatures.add(
    currentSignature
  );
}


for (
  const item of history
) {

  if (
    item.strategy_config
  ) {

    const sig =
      makeSignature(
        item.strategy_config
      );

    if (sig) {
      testedSignatures.add(sig);
    }
  }


  if (
    item.strategy &&
    item.parameters &&
    item.risk
  ) {

    const sig =
      makeSignature({

        strategy:
          item.strategy,

        parameters:
          item.parameters,

        risk:
          item.risk
      });

    if (sig) {
      testedSignatures.add(sig);
    }
  }
}


// ============================================================
// FALLBACK BUILDER
// ============================================================

function buildCandidate(
  strategy,
  parameters,
  riskOverrides = {}
) {

  return {

    strategy,

    parameters,

    risk: {

      stop_loss:
        riskOverrides.stop_loss ??
        risk.stop_loss,

      take_profit:
        riskOverrides.take_profit ??
        risk.take_profit,

      lot_size:
        riskOverrides.lot_size ??
        risk.lot_size
    },

    data: {

      instrument:
        context.instrument,

      timeframe:
        context.timeframe
    },

    capital: {

      starting_capital:
        context.starting_capital
    },

    research: {

      research_run_id:
        context.research_run_id
    }
  };
}


// ============================================================
// DETERMINISTIC FALLBACK
// ============================================================

function generateFallbackConfiguration(
  currentConfig
) {

  const candidates = [];

  const strategy =
    currentConfig?.strategy;

  const cp =
    currentConfig?.parameters || {};

  const cr =
    currentConfig?.risk || {};


  // ----------------------------------------------------------
  // EMA candidates
  // ----------------------------------------------------------

  if (
    strategy ===
    "EMA_Crossover"
  ) {

    const fast =
      safeNumber(
        cp.fast_ema,
        10
      );

    const slow =
      safeNumber(
        cp.slow_ema,
        50
      );

    const emaCandidates = [

      [fast + 1, slow],
      [fast - 1, slow],
      [fast, slow + 5],
      [fast, slow - 5],
      [fast + 2, slow + 5],
      [fast - 2, slow + 5],

      [10, 30],
      [15, 50],
      [20, 50],
      [10, 40],
      [15, 60]
    ];


    for (
      const pair of emaCandidates
    ) {

      const f = pair[0];
      const s = pair[1];

      if (
        f >= 5 &&
        f <= 30 &&
        s >= 20 &&
        s <= 100 &&
        s > f
      ) {

        candidates.push(
          buildCandidate(
            "EMA_Crossover",
            {
              fast_ema: f,
              slow_ema: s
            }
          )
        );
      }
    }
  }


  // ----------------------------------------------------------
  // RSI candidates
  // ----------------------------------------------------------

  if (
    strategy ===
    "RSI_Mean_Reversion"
  ) {

    const period =
      safeNumber(
        cp.rsi_period,
        14
      );

    const oversold =
      safeNumber(
        cp.oversold,
        30
      );

    const overbought =
      safeNumber(
        cp.overbought,
        70
      );

    const rsiCandidates = [

      [period + 1, oversold, overbought],
      [period - 1, oversold, overbought],
      [period, oversold - 5, overbought],
      [period, oversold, overbought + 5],

      [10, 30, 70],
      [14, 30, 70],
      [14, 25, 75],
      [20, 30, 70],
      [10, 25, 75]
    ];


    for (
      const candidate of rsiCandidates
    ) {

      const rp = candidate[0];
      const os = candidate[1];
      const ob = candidate[2];

      if (
        rp >= 5 &&
        rp <= 30 &&
        os >= 20 &&
        os <= 40 &&
        ob >= 60 &&
        ob <= 80 &&
        os < ob
      ) {

        candidates.push(
          buildCandidate(
            "RSI_Mean_Reversion",
            {
              rsi_period: rp,
              oversold: os,
              overbought: ob
            }
          )
        );
      }
    }
  }


  // ----------------------------------------------------------
  // Supertrend candidates
  // ----------------------------------------------------------

  if (
    strategy ===
    "Supertrend"
  ) {

    const atrPeriod =
      safeNumber(
        cp.atr_period,
        14
      );

    const multiplier =
      safeNumber(
        cp.multiplier,
        3
      );

    const supertrendCandidates = [

      [atrPeriod + 1, multiplier],
      [atrPeriod - 1, multiplier],
      [atrPeriod, multiplier + 0.5],
      [atrPeriod, multiplier - 0.5],

      [10, 2],
      [10, 3],
      [14, 2],
      [14, 3],
      [20, 3]
    ];


    for (
      const candidate of supertrendCandidates
    ) {

      const ap = candidate[0];
      const m = candidate[1];

      if (
        ap >= 5 &&
        ap <= 30 &&
        m >= 1 &&
        m <= 5
      ) {

        candidates.push(
          buildCandidate(
            "Supertrend",
            {
              atr_period: ap,
              multiplier: m
            }
          )
        );
      }
    }
  }


  // ----------------------------------------------------------
  // Cross-strategy candidates
  // ----------------------------------------------------------

  candidates.push(
    buildCandidate(
      "EMA_Crossover",
      {
        fast_ema: 10,
        slow_ema: 30
      }
    )
  );


  candidates.push(
    buildCandidate(
      "EMA_Crossover",
      {
        fast_ema: 15,
        slow_ema: 50
      }
    )
  );


  candidates.push(
    buildCandidate(
      "RSI_Mean_Reversion",
      {
        rsi_period: 14,
        oversold: 30,
        overbought: 70
      }
    )
  );


  candidates.push(
    buildCandidate(
      "RSI_Mean_Reversion",
      {
        rsi_period: 10,
        oversold: 25,
        overbought: 75
      }
    )
  );


  candidates.push(
    buildCandidate(
      "Supertrend",
      {
        atr_period: 10,
        multiplier: 2
      }
    )
  );


  candidates.push(
    buildCandidate(
      "Supertrend",
      {
        atr_period: 14,
        multiplier: 3
      }
    )
  );


  // ----------------------------------------------------------
  // Risk variations
  // ----------------------------------------------------------

  const riskVariations = [

    {
      stop_loss:
        cr.stop_loss,

      take_profit:
        cr.take_profit,

      lot_size:
        cr.lot_size
    },

    {
      stop_loss: 0.0008,
      take_profit: 0.0016,
      lot_size:
        Math.min(
          5000,
          context.starting_capital
        )
    },

    {
      stop_loss: 0.001,
      take_profit: 0.002,
      lot_size:
        Math.min(
          4000,
          context.starting_capital
        )
    },

    {
      stop_loss: 0.0015,
      take_profit: 0.003,
      lot_size:
        Math.min(
          5000,
          context.starting_capital
        )
    }
  ];


  const baseCandidates =
    [...candidates];


  for (
    const candidate of baseCandidates
  ) {

    for (
      const rv of riskVariations
    ) {

      candidates.push(
        buildCandidate(
          candidate.strategy,
          candidate.parameters,
          rv
        )
      );
    }
  }


  // ----------------------------------------------------------
  // Find unused candidate
  // ----------------------------------------------------------

  for (
    const candidate of candidates
  ) {

    const signature =
      makeSignature(
        candidate
      );

    if (
      !testedSignatures.has(
        signature
      )
    ) {

      return candidate;
    }
  }


  return null;
}


// ============================================================
// DUPLICATE DETECTION
// ============================================================

if (
  testedSignatures.has(
    proposedSignature
  )
) {

  const fallback =
    generateFallbackConfiguration(
      proposedConfig
    );


  if (!fallback) {

    throw new Error(
      "Critic proposed a duplicate configuration and no unused deterministic fallback was available."
    );
  }


  const updatedHistory =
    deepClone(
      history
    );


  const alreadyRecorded =
    updatedHistory.some(
      item =>
        Number(item.experiment) ===
        Number(context.experiment)
    );


  if (!alreadyRecorded) {

    updatedHistory.push({

      experiment:
        context.experiment,

      strategy:
        http.strategy,

      strategy_config:
        deepClone(
          http.strategy_config
        ),

      return_percent:
        http.return_percent,

      trades:
        http.trades,

      win_rate:
        http.win_rate,

      profit_factor:
        http.profit_factor,

      max_drawdown_percent:
        http.max_drawdown_percent,

      sharpe_ratio:
        http.sharpe_ratio,

      heat_score:
        currentHeatScore,

      heat_label:
        currentHeatLabel,

      heat_checks:
        currentHeatChecks,

      previous_heat_score:
        heatAnalysis.previous_heat_score,

      previous_heat_label:
        heatAnalysis.previous_heat_label,

      heat_change:
        heatAnalysis.heat_change,

      heat_assessment:
        heatAnalysis.heat_assessment
    });
  }


  return [{
    json: {

      decision:
        "MODIFY",

      retry_required:
        false,

      retry_count:
        0,

      reason:
        `${reason} Critic proposed a configuration that has already been tested. A deterministic unused configuration was selected instead.`,

      rejected_configuration:
        deepClone(
          proposedConfig
        ),

      strategy:
        fallback.strategy,

      strategy_config:
        fallback,

      fallback_used:
        true,

      fallback_reason:
        "Duplicate Critic configuration.",

      instrument:
        context.instrument,

      timeframe:
        context.timeframe,

      starting_capital:
        context.starting_capital,

      research_run_id:
        context.research_run_id,

      experiment:
        context.experiment,

      max_experiments:
        context.max_experiments,

      return_percent:
        http.return_percent,

      trades:
        http.trades,

      win_rate:
        http.win_rate,

      profit_factor:
        http.profit_factor,

      max_drawdown_percent:
        http.max_drawdown_percent,

      sharpe_ratio:
        http.sharpe_ratio,

      heat_score:
        currentHeatScore,

      heat_label:
        currentHeatLabel,

      heat_checks:
        currentHeatChecks,

      baseline_thresholds:
        baselineThresholds,

      heat_analysis:
        deepClone(
          heatAnalysis
        ),

      history:
        updatedHistory
    }
  }];
}


// ============================================================
// NORMAL VALID OUTPUT
// ============================================================

const updatedHistory =
  deepClone(
    history
  );


const alreadyRecorded =
  updatedHistory.some(
    item =>
      Number(item.experiment) ===
      Number(context.experiment)
  );


if (!alreadyRecorded) {

  updatedHistory.push({

    experiment:
      context.experiment,

    strategy:
      http.strategy,

    strategy_config:
      deepClone(
        http.strategy_config
      ),

    return_percent:
      http.return_percent,

    trades:
      http.trades,

    win_rate:
      http.win_rate,

    profit_factor:
      http.profit_factor,

    max_drawdown_percent:
      http.max_drawdown_percent,

    sharpe_ratio:
      http.sharpe_ratio,

    heat_score:
      currentHeatScore,

    heat_label:
      currentHeatLabel,

    heat_checks:
      currentHeatChecks,

    previous_heat_score:
      heatAnalysis.previous_heat_score,

    previous_heat_label:
      heatAnalysis.previous_heat_label,

    heat_change:
      heatAnalysis.heat_change,

    heat_assessment:
      heatAnalysis.heat_assessment
  });
}


// ============================================================
// FINAL OUTPUT
// ============================================================

return [{
  json: {

    decision:
      decision,

    retry_required:
      false,

    retry_count:
      0,

    reason:
      reason,

    rejected_configuration:
      null,

    strategy:
      proposedConfig.strategy,

    strategy_config:
      proposedConfig,

    fallback_used:
      false,

    fallback_reason:
      null,

    instrument:
      context.instrument,

    timeframe:
      context.timeframe,

    starting_capital:
      context.starting_capital,

    research_run_id:
      context.research_run_id,

    experiment:
      context.experiment,

    max_experiments:
      context.max_experiments,

    return_percent:
      http.return_percent,

    trades:
      http.trades,

    win_rate:
      http.win_rate,

    profit_factor:
      http.profit_factor,

    max_drawdown_percent:
      http.max_drawdown_percent,

    sharpe_ratio:
      http.sharpe_ratio,

    heat_score:
      currentHeatScore,

    heat_label:
      currentHeatLabel,

    heat_checks:
      currentHeatChecks,

    baseline_thresholds:
      baselineThresholds,

    heat_analysis:
      deepClone(
        heatAnalysis
      ),

    history:
      updatedHistory
  }
}];

const history = Array.isArray($json.history)
  ? $json.history
  : [];

if (history.length === 0) {
  throw new Error(
    "No experiment history available."
  );
}


// ---------------------------------------------------------
// Select best experiment using only performance metrics.
// No strategy-specific parameters are used here.
// ---------------------------------------------------------

let best = history[0];

for (const experiment of history) {

  const currentReturn =
    Number(experiment.return_percent);

  const bestReturn =
    Number(best.return_percent);

  // 1. Highest return
  if (currentReturn > bestReturn) {

    best = experiment;
    continue;
  }

  if (currentReturn !== bestReturn) {
    continue;
  }


  // 2. Highest profit factor
  const currentPF =
    Number(experiment.profit_factor);

  const bestPF =
    Number(best.profit_factor);

  if (currentPF > bestPF) {

    best = experiment;
    continue;
  }

  if (currentPF !== bestPF) {
    continue;
  }


  // 3. Highest Sharpe ratio
  const currentSharpe =
    Number(experiment.sharpe_ratio);

  const bestSharpe =
    Number(best.sharpe_ratio);

  if (currentSharpe > bestSharpe) {

    best = experiment;
    continue;
  }

  if (currentSharpe !== bestSharpe) {
    continue;
  }


  // 4. Better maximum drawdown
  // Example:
  // -3% is better than -5%
  const currentDrawdown =
    Number(
      experiment.max_drawdown_percent
    );

  const bestDrawdown =
    Number(
      best.max_drawdown_percent
    );

  if (
    currentDrawdown >
    bestDrawdown
  ) {

    best = experiment;
  }
}


// ---------------------------------------------------------
// Validate selected experiment
// ---------------------------------------------------------

if (
  best.experiment === undefined ||
  best.experiment === null
) {
  throw new Error(
    "Select Best Strategy could not identify a valid experiment."
  );
}


const strategyConfig =
  best.strategy_config;

if (
  !strategyConfig ||
  typeof strategyConfig !== "object" ||
  Array.isArray(strategyConfig)
) {
  throw new Error(
    "Selected experiment does not contain a valid strategy_config."
  );
}


// ---------------------------------------------------------
// Return selected experiment
// ---------------------------------------------------------

return [{
  json: {

    best_experiment:
      Number(
        best.experiment
      ),

    strategy:
      strategyConfig.strategy ||
      best.strategy,

    strategy_config:
      strategyConfig,

    return_percent:
      Number(
        best.return_percent
      ),

    trades:
      Number(
        best.trades
      ),

    win_rate:
      Number(
        best.win_rate
      ),

    profit_factor:
      Number(
        best.profit_factor
      ),

    max_drawdown_percent:
      Number(
        best.max_drawdown_percent
      ),

    sharpe_ratio:
      Number(
        best.sharpe_ratio
      ),

    history:
      history
  }
}];

const validatorOutput = $json.output;

if (
  typeof validatorOutput !== "string" ||
  validatorOutput.trim() === ""
) {
  throw new Error(
    "Validator AI output is empty or invalid."
  );
}

let text = validatorOutput
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

let aiValidation;

try {
  aiValidation = JSON.parse(text);
} catch (firstError) {
  const firstBrace = text.indexOf("{");
  const lastBrace = text.lastIndexOf("}");

  if (
    firstBrace === -1 ||
    lastBrace <= firstBrace
  ) {
    throw new Error(
      "Validator AI did not return valid JSON."
    );
  }

  try {
    aiValidation = JSON.parse(
      text.substring(
        firstBrace,
        lastBrace + 1
      )
    );
  } catch (secondError) {
    throw new Error(
      "Validator AI returned malformed JSON."
    );
  }
}


// ---------------------------------------------------------
// Deterministic validator is authoritative
// ---------------------------------------------------------

const deterministic =
  $("Deterministic Validator").item.json;

const strategyConfig =
  deterministic.strategy_config || {};

const parameters =
  strategyConfig.parameters || {};

const risk =
  strategyConfig.risk || {};

const data =
  strategyConfig.data || {};

const capital =
  strategyConfig.capital || {};

const research =
  strategyConfig.research || {};


// ---------------------------------------------------------
// Extract strategy parameters from nested config
// ---------------------------------------------------------

const fastEma =
  parameters.fast_ema !== undefined &&
  parameters.fast_ema !== null
    ? Number(parameters.fast_ema)
    : null;

const slowEma =
  parameters.slow_ema !== undefined &&
  parameters.slow_ema !== null
    ? Number(parameters.slow_ema)
    : null;

const lotSize =
  risk.lot_size !== undefined &&
  risk.lot_size !== null
    ? Number(risk.lot_size)
    : null;


// ---------------------------------------------------------
// Return final validation state
// ---------------------------------------------------------

return [{
  json: {

    validation:
      deterministic.validation,

    validation_reason:
      aiValidation.reason ||
      deterministic.validation_reason,

    validation_checks:
      deterministic.validation_checks,

    minimum_trades_required:
      deterministic.minimum_trades_required,

    best_experiment:
      Number(
        deterministic.best_experiment
      ),

    strategy:
      strategyConfig.strategy ||
      deterministic.strategy,

    strategy_config:
      strategyConfig,

    parameters:
      parameters,

    risk:
      risk,

    data:
      data,

    capital:
      capital,

    research:
      research,

    fast_ema:
      fastEma,

    slow_ema:
      slowEma,

    lot_size:
      lotSize,

    return_percent:
      Number(
        deterministic.return_percent
      ),

    trades:
      Number(
        deterministic.trades
      ),

    win_rate:
      Number(
        deterministic.win_rate
      ),

    profit_factor:
      Number(
        deterministic.profit_factor
      ),

    max_drawdown_percent:
      Number(
        deterministic.max_drawdown_percent
      ),

    sharpe_ratio:
      Number(
        deterministic.sharpe_ratio
      ),

    history:
      deterministic.history || []
  }
}];

// ============================================================
// QUANTFORGE — FINAL RESEARCH REPORT
// ============================================================
// Purpose:
//   Build the final human-readable research report from the
//   deterministic workflow output.
//
// Important:
//   Heat is NOT calculated here.
//   Heat comes from the Python backtest engine and is only
//   displayed here.
// ============================================================

const data = $json;

// ------------------------------------------------------------
// HELPERS
// ------------------------------------------------------------

function safe(value, fallback = "N/A") {
    return value === undefined || value === null
        ? fallback
        : value;
}

function formatNumber(value, decimals = 2) {
    const n = Number(value);

    if (!Number.isFinite(n)) {
        return "N/A";
    }

    return n.toFixed(decimals);
}

function formatPercent(value) {
    const n = Number(value);

    if (!Number.isFinite(n)) {
        return "N/A";
    }

    return `${n.toFixed(2)}%`;
}

function passFail(value) {
    return value ? "PASS" : "FAIL";
}

function heatText(experiment) {
    const score = safe(experiment.heat_score, "N/A");
    const label = safe(experiment.heat_label, "N/A");

    return `${score}/4 — ${label}`;
}

function formatParameters(config) {

    if (!config || typeof config !== "object") {
        return "N/A";
    }

    const parameters = config.parameters;

    if (!parameters || typeof parameters !== "object") {
        return "N/A";
    }

    const parts = [];

    for (const [key, value] of Object.entries(parameters)) {
        parts.push(`${key}: ${value}`);
    }

    return parts.join(", ");
}

function formatRisk(config) {

    if (!config || typeof config !== "object") {
        return "N/A";
    }

    const risk = config.risk;

    if (!risk || typeof risk !== "object") {
        return "N/A";
    }

    return [
        `stop_loss: ${safe(risk.stop_loss)}`,
        `take_profit: ${safe(risk.take_profit)}`,
        `lot_size: ${safe(risk.lot_size)}`
    ].join(", ");
}

function formatData(config) {

    if (!config || typeof config !== "object") {
        return "N/A";
    }

    const dataConfig = config.data;

    if (!dataConfig || typeof dataConfig !== "object") {
        return "N/A";
    }

    return [
        `instrument: ${safe(dataConfig.instrument)}`,
        `timeframe: ${safe(dataConfig.timeframe)}`
    ].join(", ");
}

function formatCapital(config) {

    if (!config || typeof config !== "object") {
        return "N/A";
    }

    const capital = config.capital;

    if (!capital || typeof capital !== "object") {
        return "N/A";
    }

    return `starting_capital: ${safe(capital.starting_capital)}`;
}

function formatResearch(config) {

    if (!config || typeof config !== "object") {
        return "N/A";
    }

    const research = config.research;

    if (!research || typeof research !== "object") {
        return "N/A";
    }

    return `research_run_id: ${safe(research.research_run_id)}`;
}


// ------------------------------------------------------------
// EXTRACT CORE DATA
// ------------------------------------------------------------

const strategyConfig = data.strategy_config || {};

const strategy =
    data.strategy ||
    strategyConfig.strategy ||
    "N/A";

const history =
    Array.isArray(data.history)
        ? data.history
        : [];

const bestExperiment = data.best_experiment;

const validation =
    data.validation ||
    "UNKNOWN";

const validationChecks =
    data.validation_checks &&
    typeof data.validation_checks === "object"
        ? data.validation_checks
        : {};

const validationReason =
    data.validation_reason ||
    "No validator explanation provided.";

const researchObjective =
    data.research_objective ||
    "Not provided.";

const instrument =
    data.instrument ||
    strategyConfig?.data?.instrument ||
    "N/A";

const timeframe =
    data.timeframe ||
    strategyConfig?.data?.timeframe ||
    "N/A";


// ------------------------------------------------------------
// FIND BEST EXPERIMENT FROM HISTORY
// ------------------------------------------------------------

let bestExperimentData = null;

if (history.length > 0) {

    bestExperimentData = history.find(
        experiment =>
            Number(experiment.experiment) === Number(bestExperiment)
    );

    // Fallback if exact experiment number wasn't found.
    if (!bestExperimentData) {

        bestExperimentData = history[history.length - 1];
    }
}


// ------------------------------------------------------------
// FINAL METRICS
// ------------------------------------------------------------

const finalReturn =
    bestExperimentData?.return_percent ??
    data.return_percent;

const finalTrades =
    bestExperimentData?.trades ??
    data.trades;

const finalWinRate =
    bestExperimentData?.win_rate ??
    data.win_rate;

const finalProfitFactor =
    bestExperimentData?.profit_factor ??
    data.profit_factor;

const finalDrawdown =
    bestExperimentData?.max_drawdown_percent ??
    data.max_drawdown_percent;

const finalSharpe =
    bestExperimentData?.sharpe_ratio ??
    data.sharpe_ratio;

const finalHeatScore =
    bestExperimentData?.heat_score ??
    data.heat_score;

const finalHeatLabel =
    bestExperimentData?.heat_label ??
    data.heat_label;

const finalHeatChecks =
    bestExperimentData?.heat_checks ??
    data.heat_checks ??
    {};


// ------------------------------------------------------------
// BUILD REPORT
// ------------------------------------------------------------

let report = "";

report += "QUANTFORGE RESEARCH REPORT\n";
report += "===========================\n\n";

report += `Research Objective:\n`;
report += `${researchObjective}\n\n`;

report += `Instrument: ${instrument}\n`;
report += `Timeframe: ${timeframe}\n`;
report += `Strategy: ${strategy}\n`;
report += `Experiments Conducted: ${history.length}\n\n`;


// ============================================================
// EXPERIMENT RESULTS
// ============================================================

report += "EXPERIMENT RESULTS\n";
report += "------------------\n\n";

for (let index = 0; index < history.length; index++) {

    const experiment = history[index];

    if (!experiment || typeof experiment !== "object") {
        continue;
    }

    const config =
        experiment.strategy_config &&
        typeof experiment.strategy_config === "object"
            ? experiment.strategy_config
            : {};

    report += `Experiment ${safe(experiment.experiment, index + 1)}\n`;

    report += `Strategy: ${safe(
        config.strategy || experiment.strategy,
        "N/A"
    )}\n`;

    report += `Parameters: ${formatParameters(config)}\n`;

    report += `Risk: ${formatRisk(config)}\n`;

    report += `Data: ${formatData(config)}\n`;

    report += `Capital: ${formatCapital(config)}\n`;

    report += `Research: ${formatResearch(config)}\n`;

    report += `Return: ${formatPercent(experiment.return_percent)}\n`;

    report += `Trades: ${safe(experiment.trades)}\n`;

    report += `Win Rate: ${formatPercent(experiment.win_rate)}\n`;

    report += `Profit Factor: ${formatNumber(
        experiment.profit_factor
    )}\n`;

    report += `Maximum Drawdown: ${formatPercent(
        experiment.max_drawdown_percent
    )}\n`;

    report += `Sharpe Ratio: ${formatNumber(
        experiment.sharpe_ratio
    )}\n`;

    // --------------------------------------------------------
    // HEAT
    // --------------------------------------------------------

    report += `Heat Score: ${heatText(experiment)}\n`;

    const heatChecks =
        experiment.heat_checks &&
        typeof experiment.heat_checks === "object"
            ? experiment.heat_checks
            : {};

    report += "Heat Checks:\n";

    report += `  Positive Return: ${passFail(
        heatChecks.positive_return
    )}\n`;

    report += `  Profit Factor > 1: ${passFail(
        heatChecks.profit_factor_above_1
    )}\n`;

    report += `  Sharpe Ratio > 0: ${passFail(
        heatChecks.positive_sharpe
    )}\n`;

    report += `  Drawdown > -10%: ${passFail(
        heatChecks.drawdown_better_than_10_percent
    )}\n`;

    report += "\n";
}


// ============================================================
// HEAT PROGRESSION
// ============================================================

report += "HEAT PROGRESSION\n";
report += "----------------\n\n";

if (history.length === 0) {

    report += "No experiment history available.\n\n";

} else {

    for (let index = 0; index < history.length; index++) {

        const experiment = history[index];

        if (!experiment || typeof experiment !== "object") {
            continue;
        }

        report +=
            `Experiment ${safe(experiment.experiment, index + 1)}: ` +
            `${heatText(experiment)}\n`;
    }

    report += "\n";

    for (let index = 1; index < history.length; index++) {

        const previous = history[index - 1];
        const current = history[index];

        const previousScore = Number(previous.heat_score);
        const currentScore = Number(current.heat_score);

        if (
            Number.isFinite(previousScore) &&
            Number.isFinite(currentScore)
        ) {

            const change = currentScore - previousScore;

            const sign =
                change > 0
                    ? "+"
                    : "";

            report +=
                `Experiment ${previous.experiment} → ` +
                `Experiment ${current.experiment}: ` +
                `${sign}${change} Heat points\n`;
        }
    }

    report += "\n";
}


// ============================================================
// BEST STRATEGY
// ============================================================

report += "BEST STRATEGY\n";
report += "-------------\n";

report += `Experiment: ${safe(bestExperiment)}\n`;

report += `Strategy: ${strategy}\n`;

report += `Parameters: ${formatParameters(strategyConfig)}\n`;

report += `Risk: ${formatRisk(strategyConfig)}\n`;

report += `Data: ${formatData(strategyConfig)}\n`;

report += `Capital: ${formatCapital(strategyConfig)}\n`;

report += `Research: ${formatResearch(strategyConfig)}\n`;

report += `Return: ${formatPercent(finalReturn)}\n`;

report += `Trades: ${safe(finalTrades)}\n`;

report += `Win Rate: ${formatPercent(finalWinRate)}\n`;

report += `Profit Factor: ${formatNumber(finalProfitFactor)}\n`;

report += `Maximum Drawdown: ${formatPercent(finalDrawdown)}\n`;

report += `Sharpe Ratio: ${formatNumber(finalSharpe)}\n`;

report += `Heat Score: ${safe(finalHeatScore)}/4\n`;

report += `Heat Label: ${safe(finalHeatLabel)}\n`;

report += "\n";

report += "Heat Checks:\n";

report += `Positive Return: ${passFail(
    finalHeatChecks.positive_return
)}\n`;

report += `Profit Factor > 1: ${passFail(
    finalHeatChecks.profit_factor_above_1
)}\n`;

report += `Sharpe Ratio > 0: ${passFail(
    finalHeatChecks.positive_sharpe
)}\n`;

report += `Maximum Drawdown > -10%: ${passFail(
    finalHeatChecks.drawdown_better_than_10_percent
)}\n`;

report += "\n";


// ============================================================
// VALIDATION
// ============================================================

report += "VALIDATION\n";
report += "----------\n";

report += `Validation: ${validation}\n\n`;

report += "Validation Checks:\n";

report += `Positive Return: ${passFail(
    validationChecks.positive_return
)}\n`;

report += `Profit Factor > 1: ${passFail(
    validationChecks.profit_factor_above_1
)}\n`;

report += `Sharpe Ratio > 0: ${passFail(
    validationChecks.positive_sharpe
)}\n`;

report += `Maximum Drawdown > -10%: ${passFail(
    validationChecks.drawdown_better_than_10_percent
)}\n`;

report += `Trade Count >= 100: ${passFail(
    validationChecks.reasonable_trade_count
)}\n`;

report += "\n";

report += "Validator Explanation:\n";
report += `${validationReason}\n\n`;


// ============================================================
// CONCLUSION
// ============================================================

report += "CONCLUSION\n";
report += "----------\n";

report +=
    `Experiment ${safe(bestExperiment)} was selected as ` +
    `the best candidate from the experiments conducted. `;

report +=
    `The selected configuration produced a return of ` +
    `${formatPercent(finalReturn)}, ` +
    `profit factor of ${formatNumber(finalProfitFactor)}, ` +
    `Sharpe ratio of ${formatNumber(finalSharpe)}, ` +
    `and maximum drawdown of ${formatPercent(finalDrawdown)}. `;

report +=
    `Its deterministic Heat Score was ` +
    `${safe(finalHeatScore)}/4 (${safe(finalHeatLabel)}). `;

report +=
    `The deterministic validation stage marked the strategy ` +
    `as ${validation}.`;


// ------------------------------------------------------------
// OUTPUT
// ------------------------------------------------------------

return [
    {
        json: {
            ...data,

            report,

            // Explicit reporting fields
            report_instrument: instrument,
            report_timeframe: timeframe,
            report_strategy: strategy,

            final_heat_score: finalHeatScore,
            final_heat_label: finalHeatLabel,
            final_heat_checks: finalHeatChecks,

            report_best_experiment: bestExperiment,

            // Filename convention:
            // <instrument>_<timeframe>_<strategy>.pdf
            report_filename:null
        }
    }
];

const best = $json;

const minTrades = 100;

const checks = {
  positive_return: Number(best.return_percent) > 0,
  profit_factor_above_1: Number(best.profit_factor) > 1,
  positive_sharpe: Number(best.sharpe_ratio) > 0,
  drawdown_better_than_10_percent: Number(best.max_drawdown_percent) > -10,
  reasonable_trade_count: Number(best.trades) >= minTrades
};

const passed = Object.values(checks).every(Boolean);

const failedChecks = Object.entries(checks)
  .filter(([key, value]) => !value)
  .map(([key]) => key);

let validationReason;

if (passed) {
  validationReason =
    "The strategy satisfies all deterministic validation criteria.";
} else {
  validationReason =
    "The strategy failed the following validation criteria: " +
    failedChecks.join(", ") + ".";
}

return [{
  json: {
    ...best,

    validation: passed ? "PASS" : "FAIL",

    validation_checks: checks,

    validation_reason: validationReason,

    minimum_trades_required: minTrades
  }
}];

const config = $json.strategy_config;

if (!config || typeof config !== "object") {
  throw new Error("Researcher did not provide a valid strategy_config.");
}

if (!config.strategy) {
  throw new Error("strategy_config.strategy is missing.");
}

if (!config.parameters || typeof config.parameters !== "object") {
  throw new Error("strategy_config.parameters is missing or invalid.");
}

if (!config.risk || typeof config.risk !== "object") {
  throw new Error("strategy_config.risk is missing or invalid.");
}

if (!config.data || typeof config.data !== "object") {
  throw new Error("strategy_config.data is missing or invalid.");
}

if (!config.capital || typeof config.capital !== "object") {
  throw new Error("strategy_config.capital is missing or invalid.");
}

if (!config.research || typeof config.research !== "object") {
  throw new Error("strategy_config.research is missing or invalid.");
}


// ---------------------------------------------------------
// Supported strategy families
// ---------------------------------------------------------

const supportedStrategies = [
  "EMA_Crossover",
  "RSI_Mean_Reversion",
  "Supertrend"
];

if (!supportedStrategies.includes(config.strategy)) {
  throw new Error(
    `Unsupported strategy family: ${config.strategy}`
  );
}


// ---------------------------------------------------------
// Preserve complete configuration
// ---------------------------------------------------------

const strategyConfig = {
  strategy: config.strategy,
  parameters: config.parameters,
  risk: config.risk,
  data: config.data,
  research: config.research,
  capital: config.capital
};


// ---------------------------------------------------------
// Compatibility fields
// ---------------------------------------------------------
// These are kept because the current HTTP Request and some
// existing n8n nodes still reference them.

const parameters = strategyConfig.parameters;
const risk = strategyConfig.risk;

return [
  {
    json: {
      ...$json,

      strategy_config: strategyConfig,

      strategy: strategyConfig.strategy,

      fast_ema:
        parameters.fast_ema !== undefined
          ? Number(parameters.fast_ema)
          : null,

      slow_ema:
        parameters.slow_ema !== undefined
          ? Number(parameters.slow_ema)
          : null,

      rsi_period:
        parameters.rsi_period !== undefined
          ? Number(parameters.rsi_period)
          : null,

      oversold:
        parameters.oversold !== undefined
          ? Number(parameters.oversold)
          : null,

      overbought:
        parameters.overbought !== undefined
          ? Number(parameters.overbought)
          : null,

      atr_period:
        parameters.atr_period !== undefined
          ? Number(parameters.atr_period)
          : null,

      multiplier:
        parameters.multiplier !== undefined
          ? Number(parameters.multiplier)
          : null,

      stop_loss:
        risk.stop_loss !== undefined
          ? Number(risk.stop_loss)
          : null,

      take_profit:
        risk.take_profit !== undefined
          ? Number(risk.take_profit)
          : null,

      lot_size:
        risk.lot_size !== undefined
          ? Number(risk.lot_size)
          : null
    }
  }
];

// ============================================================
// QuantForge - Researcher Parser
// Robust parser for Ollama / n8n AI output
// ============================================================

const MAX_RETRIES = 3;

// ------------------------------------------------------------
// Helpers
// ------------------------------------------------------------

function deepClone(value) {
  return value === undefined
    ? undefined
    : JSON.parse(JSON.stringify(value));
}

function safeNumber(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function isInteger(value) {
  return Number.isInteger(Number(value));
}

function makeSignature(config) {
  if (!config) return "";

  return JSON.stringify({
    strategy: config.strategy,
    parameters: config.parameters,
    risk: config.risk
  });
}

function extractJsonObject(text) {
  if (!text || typeof text !== "string") return null;

  const cleaned = text
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  // First try the entire response
  try {
    const parsed = JSON.parse(cleaned);

    if (parsed && typeof parsed === "object") {
      return parsed;
    }
  } catch {}

  // Then search for a balanced JSON object
  const start = cleaned.indexOf("{");

  if (start === -1) {
    return null;
  }

  let depth = 0;
  let inString = false;
  let escaped = false;

  for (let i = start; i < cleaned.length; i++) {
    const char = cleaned[i];

    if (escaped) {
      escaped = false;
      continue;
    }

    if (char === "\\") {
      escaped = true;
      continue;
    }

    if (char === '"') {
      inString = !inString;
      continue;
    }

    if (inString) continue;

    if (char === "{") {
      depth++;
    } else if (char === "}") {
      depth--;

      if (depth === 0) {
        const candidate = cleaned.slice(start, i + 1);

        try {
          const parsed = JSON.parse(candidate);

          if (parsed && typeof parsed === "object") {
            return parsed;
          }
        } catch {
          return null;
        }
      }
    }
  }

  return null;
}

// ------------------------------------------------------------
// Get incoming data
// ------------------------------------------------------------

const incoming = $input.first().json;

// ------------------------------------------------------------
// IMPORTANT:
// Get authoritative research values from Edit Fields.
// These must NOT be trusted from the LLM.
// ------------------------------------------------------------

let editFields = {};

try {
  editFields = $("Edit Fields").first().json || {};
} catch {
  editFields = {};
}

const instrument =
  editFields.instrument ||
  incoming.instrument ||
  "EURUSD";

const timeframe =
  editFields.timeframe ||
  incoming.timeframe ||
  "15m";

const startingCapital =
  safeNumber(
    editFields.starting_capital ??
    editFields.initial_capital ??
    incoming.starting_capital ??
    incoming.initial_capital ??
    10000
  );

const researchObjective =
  editFields.research_objective ||
  incoming.research_objective ||
  "";

const experiment =
  safeNumber(
    editFields.experiment ??
    incoming.experiment ??
    1
  );

const maxExperiments =
  safeNumber(
    editFields.max_experiments ??
    incoming.max_experiments ??
    5
  );

const researchRunId =
  editFields.research_run_id ||
  incoming.research_run_id ||
  "manual_run";

// ------------------------------------------------------------
// Preserve existing state
// ------------------------------------------------------------

const history = Array.isArray(incoming.history)
  ? deepClone(incoming.history)
  : [];

const retryCount = safeNumber(incoming.retry_count) ?? 0;

const heatAnalysis = incoming.heat_analysis
  ? deepClone(incoming.heat_analysis)
  : null;

// ------------------------------------------------------------
// Extract AI output
//
// IMPORTANT:
// Your actual node output is:
//
// ai: [
//   {
//     output: "..."
//   }
// ]
//
// So we explicitly support that structure.
// ------------------------------------------------------------

let rawAIOutput = null;

// Structure shown in your execution output
if (
  Array.isArray(incoming.ai) &&
  incoming.ai.length > 0 &&
  typeof incoming.ai[0] === "object"
) {
  rawAIOutput = incoming.ai[0].output;
}

// Direct output fallback
if (!rawAIOutput && typeof incoming.output === "string") {
  rawAIOutput = incoming.output;
}

// Other common n8n AI structures
if (!rawAIOutput && typeof incoming.text === "string") {
  rawAIOutput = incoming.text;
}

if (
  !rawAIOutput &&
  incoming.response &&
  typeof incoming.response === "string"
) {
  rawAIOutput = incoming.response;
}

// ------------------------------------------------------------
// Parse AI output
// ------------------------------------------------------------

let parsedAI = null;

if (rawAIOutput && typeof rawAIOutput === "string") {
  parsedAI = extractJsonObject(rawAIOutput);
} else if (
  rawAIOutput &&
  typeof rawAIOutput === "object"
) {
  parsedAI = rawAIOutput;
}

// Sometimes the AI may return:
//
// {
//   strategy_config: {...}
// }
//
// Sometimes the extracted object itself is the config.
//
// Normalize both.
// ------------------------------------------------------------

let strategyConfig = null;

if (parsedAI && parsedAI.strategy_config) {
  strategyConfig = deepClone(parsedAI.strategy_config);
} else if (
  parsedAI &&
  parsedAI.strategy
) {
  strategyConfig = deepClone(parsedAI);
}

// ------------------------------------------------------------
// Retry helper
// ------------------------------------------------------------

function retry(reason, rejectedConfig = null) {

  const nextRetryCount = retryCount + 1;

  return {
    retry_required: true,

    retry_reason: reason,

    retry_count: nextRetryCount,

    research_objective: researchObjective,

    instrument,

    timeframe,

    starting_capital: startingCapital,

    initial_capital: startingCapital,

    experiment,

    max_experiments: maxExperiments,

    research_run_id: researchRunId,

    history,

    heat_analysis: heatAnalysis,

    rejected_configuration: rejectedConfig
      ? deepClone(rejectedConfig)
      : null
  };
}

// ------------------------------------------------------------
// If AI output could not be parsed
// ------------------------------------------------------------

if (!strategyConfig) {

  if (retryCount < MAX_RETRIES) {
    return [
      {
        json: retry(
          "Researcher AI output could not be parsed as valid JSON."
        )
      }
    ];
  }

  throw new Error(
    "Researcher AI failed to produce valid JSON after maximum retries."
  );
}

// ------------------------------------------------------------
// Strategy validation
// ------------------------------------------------------------

const supportedStrategies = [
  "EMA_Crossover",
  "RSI_Mean_Reversion",
  "Supertrend"
];

if (!supportedStrategies.includes(strategyConfig.strategy)) {

  if (retryCount < MAX_RETRIES) {
    return [
      {
        json: retry(
          `Unsupported strategy: ${strategyConfig.strategy}`,
          strategyConfig
        )
      }
    ];
  }

  throw new Error(
    `Unsupported strategy after maximum retries: ${strategyConfig.strategy}`
  );
}

// ------------------------------------------------------------
// Ensure required objects exist
// ------------------------------------------------------------

if (
  !strategyConfig.parameters ||
  typeof strategyConfig.parameters !== "object"
) {
  strategyConfig.parameters = {};
}

if (
  !strategyConfig.risk ||
  typeof strategyConfig.risk !== "object"
) {
  strategyConfig.risk = {};
}

// ------------------------------------------------------------
// Strategy-specific validation
// ------------------------------------------------------------

const p = strategyConfig.parameters;

// EMA
if (strategyConfig.strategy === "EMA_Crossover") {

  const fast = safeNumber(p.fast_ema);
  const slow = safeNumber(p.slow_ema);

  if (
    fast === null ||
    slow === null ||
    !isInteger(fast) ||
    !isInteger(slow) ||
    fast < 5 ||
    fast > 30 ||
    slow < 20 ||
    slow > 100 ||
    slow <= fast
  ) {

    if (retryCount < MAX_RETRIES) {
      return [
        {
          json: retry(
            "Invalid EMA parameters. fast_ema must be 5-30, slow_ema must be 20-100, and slow_ema must be greater than fast_ema.",
            strategyConfig
          )
        }
      ];
    }

    throw new Error(
      "Invalid EMA parameters after maximum retries."
    );
  }
}

// RSI
if (strategyConfig.strategy === "RSI_Mean_Reversion") {

  const period = safeNumber(p.rsi_period);
  const oversold = safeNumber(p.oversold);
  const overbought = safeNumber(p.overbought);

  if (
    period === null ||
    oversold === null ||
    overbought === null ||
    !isInteger(period) ||
    period < 5 ||
    period > 30 ||
    oversold < 20 ||
    oversold > 40 ||
    overbought < 60 ||
    overbought > 80 ||
    oversold >= overbought
  ) {

    if (retryCount < MAX_RETRIES) {
      return [
        {
          json: retry(
            "Invalid RSI parameters.",
            strategyConfig
          )
        }
      ];
    }

    throw new Error(
      "Invalid RSI parameters after maximum retries."
    );
  }
}

// Supertrend
if (strategyConfig.strategy === "Supertrend") {

  const atrPeriod = safeNumber(p.atr_period);
  const multiplier = safeNumber(p.multiplier);

  if (
    atrPeriod === null ||
    multiplier === null ||
    !isInteger(atrPeriod) ||
    atrPeriod < 5 ||
    atrPeriod > 30 ||
    multiplier < 1 ||
    multiplier > 5
  ) {

    if (retryCount < MAX_RETRIES) {
      return [
        {
          json: retry(
            "Invalid Supertrend parameters.",
            strategyConfig
          )
        }
      ];
    }

    throw new Error(
      "Invalid Supertrend parameters after maximum retries."
    );
  }
}

// ------------------------------------------------------------
// Validate risk
// ------------------------------------------------------------

const stopLoss = safeNumber(strategyConfig.risk.stop_loss);
const takeProfit = safeNumber(strategyConfig.risk.take_profit);
const lotSize = safeNumber(strategyConfig.risk.lot_size);

if (
  stopLoss === null ||
  takeProfit === null ||
  lotSize === null ||
  stopLoss <= 0 ||
  takeProfit <= 0 ||
  lotSize <= 0 ||
  lotSize > startingCapital
) {

  if (retryCount < MAX_RETRIES) {
    return [
      {
        json: retry(
          "Invalid risk parameters. stop_loss, take_profit and lot_size must be positive and lot_size must not exceed starting capital.",
          strategyConfig
        )
      }
    ];
  }

  throw new Error(
    "Invalid risk parameters after maximum retries."
  );
}

// ------------------------------------------------------------
// CRITICAL:
// Overwrite immutable system-controlled fields.
//
// DO NOT TRUST THE LLM FOR THESE.
// ------------------------------------------------------------

strategyConfig.data = {
  instrument: instrument,
  timeframe: timeframe
};

strategyConfig.capital = {
  starting_capital: startingCapital
};

strategyConfig.research = {
  research_run_id: researchRunId
};

// ------------------------------------------------------------
// Normalize risk
// ------------------------------------------------------------

strategyConfig.risk = {
  stop_loss: stopLoss,
  take_profit: takeProfit,
  lot_size: lotSize
};

// ------------------------------------------------------------
// Duplicate detection
// ------------------------------------------------------------

const currentSignature = makeSignature(strategyConfig);

const duplicate = history.some(item => {

  if (!item || !item.strategy_config) {
    return false;
  }

  return makeSignature(item.strategy_config) === currentSignature;
});

if (duplicate) {

  if (retryCount < MAX_RETRIES) {
    return [
      {
        json: retry(
          "Researcher generated a strategy configuration that was already tested.",
          strategyConfig
        )
      }
    ];
  }

  throw new Error(
    "Researcher repeatedly generated duplicate strategy configurations."
  );
}

// ------------------------------------------------------------
// SUCCESS
// ------------------------------------------------------------

return [
  {
    json: {

      retry_required: false,

      retry_reason: "",

      retry_count: retryCount,

      research_objective: researchObjective,

      instrument,

      timeframe,

      starting_capital: startingCapital,

      initial_capital: startingCapital,

      experiment,

      max_experiments: maxExperiments,

      research_run_id: researchRunId,

      strategy_config: strategyConfig,

      history,

      heat_analysis: heatAnalysis
    }
  }
];

const current = $json;

const strategyConfig =
  current.strategy_config || {};

const history =
  Array.isArray(current.history)
    ? current.history
    : [];

const dataConfig =
  strategyConfig.data || {};

const capitalConfig =
  strategyConfig.capital || {};

const researchConfig =
  strategyConfig.research || {};

return [{
  json: {

    // ---------------------------------------------------
    // Decision from Critic
    // ---------------------------------------------------

    decision:
      current.decision,

    reason:
      current.reason,

    // ---------------------------------------------------
    // Research state
    // ---------------------------------------------------

    research_objective:
      current.research_objective,

    research_run_id:
      current.research_run_id ||
      researchConfig.research_run_id,

    instrument:
      current.instrument ||
      dataConfig.instrument,

    timeframe:
      current.timeframe ||
      dataConfig.timeframe,

    starting_capital:
      Number(
        current.starting_capital ||
        capitalConfig.starting_capital ||
        10000
      ),

    experiment:
      Number(
        current.experiment || 1
      ),

    max_experiments:
      Number(
        current.max_experiments || 5
      ),

    // ---------------------------------------------------
    // Strategy configuration
    // ---------------------------------------------------

    strategy:
      strategyConfig.strategy ||
      current.strategy,

    strategy_config:
      strategyConfig,

    // ---------------------------------------------------
    // Compatibility fields
    // ---------------------------------------------------

    fast_ema:
      Number(
        strategyConfig.parameters?.fast_ema ??
        current.fast_ema ??
        0
      ),

    slow_ema:
      Number(
        strategyConfig.parameters?.slow_ema ??
        current.slow_ema ??
        0
      ),

    lot_size:
      strategyConfig.risk?.lot_size !== null &&
      strategyConfig.risk?.lot_size !== undefined
        ? Number(
            strategyConfig.risk.lot_size
          )
        : null,

    // ---------------------------------------------------
    // Experiment history
    // ---------------------------------------------------

    history:
      history
  }
}];

// ============================================================
// QUANTFORGE — PREPARE PDF PAYLOAD
// ============================================================

const payload = {
    ...$json
};

// ------------------------------------------------------------
// BASIC VALIDATION
// ------------------------------------------------------------

if (!payload.strategy_config) {
    throw new Error(
        "PDF payload error: strategy_config is missing."
    );
}

if (!Array.isArray(payload.history)) {
    throw new Error(
        "PDF payload error: history is missing or is not an array."
    );
}

if (payload.best_experiment === undefined) {
    throw new Error(
        "PDF payload error: best_experiment is missing."
    );
}

if (!payload.validation) {
    throw new Error(
        "PDF payload error: validation result is missing."
    );
}

// ------------------------------------------------------------
// VERIFY HEAT EXISTS
// ------------------------------------------------------------

for (const experiment of payload.history) {

    if (!experiment || typeof experiment !== "object") {
        continue;
    }

    if (
        experiment.heat_score === undefined ||
        experiment.heat_label === undefined
    ) {
        throw new Error(
            `PDF payload error: Heat data missing for experiment ${
                experiment.experiment ?? "unknown"
            }.`
        );
    }
}

// ------------------------------------------------------------
// METADATA
// ------------------------------------------------------------

const strategyConfig =
    payload.strategy_config || {};

const dataConfig =
    strategyConfig.data || {};

const instrument =
    payload.instrument ||
    dataConfig.instrument;

const timeframe =
    payload.timeframe ||
    dataConfig.timeframe;

const strategy =
    payload.strategy ||
    strategyConfig.strategy;

// ------------------------------------------------------------
// RESEARCH OBJECTIVE
// ------------------------------------------------------------

// Pull the original objective directly from Edit Fields.
// This prevents it from being lost during the experiment loop.
let researchObjective = "";

try {
    researchObjective =
        $("Edit Fields").first().json.research_objective || "";
} catch (error) {
    researchObjective =
        payload.research_objective || "";
}

if (!researchObjective) {
    researchObjective =
        payload.research_objective || "";
}

payload.research_objective = researchObjective;

if (!instrument) {
    throw new Error(
        "PDF payload error: instrument is missing."
    );
}

if (!timeframe) {
    throw new Error(
        "PDF payload error: timeframe is missing."
    );
}

if (!strategy) {
    throw new Error(
        "PDF payload error: strategy is missing."
    );
}

// ------------------------------------------------------------
// REPORT METADATA
// ------------------------------------------------------------

payload.report_instrument = instrument;
payload.report_timeframe = timeframe;
payload.report_strategy = strategy;

payload.report_filename = null;

// ------------------------------------------------------------
// RETURN NORMAL JSON
// ------------------------------------------------------------

return [
    {
        json: payload
    }
];

// ============================================================
// QuantForge - Deterministic Heat Analysis
// Runs AFTER HTTP Request and BEFORE Critic AI
// ============================================================

const data = $input.first().json;

const history = Array.isArray(data.history)
  ? JSON.parse(JSON.stringify(data.history))
  : [];

const currentHeatScore =
  Number.isFinite(Number(data.heat_score))
    ? Number(data.heat_score)
    : null;

const currentHeatLabel =
  data.heat_label ?? null;

// ------------------------------------------------------------
// Previous experiment
// ------------------------------------------------------------

let previousHeatScore = null;
let previousHeatLabel = null;

if (history.length > 0) {

  const previous = history[history.length - 1];

  if (
    previous.heat_score !== undefined &&
    previous.heat_score !== null
  ) {
    previousHeatScore = Number(previous.heat_score);
  }

  previousHeatLabel =
    previous.heat_label ?? null;
}

// ------------------------------------------------------------
// Heat change
// ------------------------------------------------------------

let heatChange = null;
let heatAssessment = "BASELINE";

if (
  previousHeatScore !== null &&
  currentHeatScore !== null
) {

  heatChange =
    currentHeatScore - previousHeatScore;

  if (heatChange > 0) {
    heatAssessment = "IMPROVED";
  }
  else if (heatChange < 0) {
    heatAssessment = "DECLINED";
  }
  else {
    heatAssessment = "UNCHANGED";
  }
}

// ------------------------------------------------------------
// Return everything from HTTP Request plus deterministic Heat
// ------------------------------------------------------------

return [{
  json: {

    ...data,

    heat_analysis: {

      current_heat_score:
        currentHeatScore,

      current_heat_label:
        currentHeatLabel,

      previous_heat_score:
        previousHeatScore,

      previous_heat_label:
        previousHeatLabel,

      heat_change:
        heatChange,

      heat_assessment:
        heatAssessment
    }
  }
}];

// ============================================================
// QUANTFORGE — PDF RESULT PARSER
// ============================================================
// Purpose:
// 1. Parse report_generator.py output
// 2. Preserve the complete final research payload
// 3. Return dashboard-ready JSON
// ============================================================

const stdout = $json.stdout;

if (!stdout) {
    throw new Error(
        "PDF generation returned no output."
    );
}

let result;

try {
    result = JSON.parse(
        stdout.trim()
    );
} catch (error) {
    throw new Error(
        "Could not parse report_generator.py output.\n\n" +
        stdout
    );
}

if (!result.report_path) {
    throw new Error(
        "PDF generator did not return report_path."
    );
}


// ------------------------------------------------------------
// Get the complete payload that was sent to PDF generator
// ------------------------------------------------------------

let payload = {};

try {
    payload =
        $("Prepare PDF Payload").first().json || {};
} catch (error) {
    payload = {};
}


// ------------------------------------------------------------
// Merge PDF result with research result
// ------------------------------------------------------------

const finalResult = {

    ...payload,

    pdf_generated: true,

    report_path:
        result.report_path,

    report_filename:
        result.report_filename,

    instrument:
        result.instrument ||
        payload.instrument,

    timeframe:
        result.timeframe ||
        payload.timeframe,

    strategy:
        result.strategy ||
        payload.strategy,

    best_experiment:
        result.best_experiment ??
        payload.best_experiment,

    experiments:
        result.experiments ??
        payload.history ??
        [],

    heat_score:
        result.heat_score ??
        payload.heat_score,

    heat_label:
        result.heat_label ??
        payload.heat_label,

    trades_used_for_charts:
        result.trades_used_for_charts ??
        null

};


// ------------------------------------------------------------
// Make dashboard fields explicit
// ------------------------------------------------------------

finalResult.dashboard = {

    research_objective:
        payload.research_objective ||
        "",

    instrument:
        finalResult.instrument ||
        "",

    timeframe:
        finalResult.timeframe ||
        "",

    starting_capital:
        payload.starting_capital ??
        payload.capital?.starting_capital ??
        null,

    strategy:
        finalResult.strategy ||
        "",

    best_experiment:
        finalResult.best_experiment ??
        null,

    return_percent:
        payload.return_percent ??
        null,

    trades:
        payload.trades ??
        null,

    win_rate:
        payload.win_rate ??
        null,

    profit_factor:
        payload.profit_factor ??
        null,

    max_drawdown_percent:
        payload.max_drawdown_percent ??
        null,

    sharpe_ratio:
        payload.sharpe_ratio ??
        null,

    heat_score:
        finalResult.heat_score ??
        null,

    heat_label:
        finalResult.heat_label ??
        null,

    validation:
        payload.validation ??
        null,

    validation_reason:
        payload.validation_reason ??
        "",

    validation_checks:
        payload.validation_checks ??
        {},

    experiments:
        payload.history ??
        [],

    report_filename:
        finalResult.report_filename ||
        "",

    report_path:
        finalResult.report_path ||
        ""

};


return [
    {
        json: finalResult
    }
];

